    def get_changes(
            api: AppCommand,
            local: AppCommand
    ) -> Dict[str, Any]:
        update: Dict[str, Any] = {}

        if api.description != local.description:
            update["description"] = local.description

        if api.default_permission != local.default_permission:
            update["default_permission"] = local.default_permission

        options: List[Dict[str, Any]] = []
